const mod=P.mods.people;if(!mod||!PC||!PR||!IE)return;
const esc=P.esc,fa=P.fa,A=x=>Array.isArray(x)?x:[],Z=v=>{const n=Number(v);return Number.isFinite(n)?n:0},S=x=>String(x??'').trim(),pad=n=>String(n).padStart(2,'0');
const T=v=>P.mt(Math.round(Z(v))),TS=v=>{const r=Math.round(Z(v));return r<0?`<span class="down">−${P.mt(-r)}</span>`:P.mt(r)};
const H=()=>PR.doc(),staff=()=>A(H()?.personnel),person=id=>staff().find(p=>p.id===id);
