function ym(){const ms=PC.months(H(),today());if(!ms.length)return[0,0];if(!st.y||!ms.some(x=>x.year===st.y&&x.month===st.m)){const x=ms.length>1?ms.at(-2):ms.at(-1);st.y=x.year;st.m=x.month}return[st.y,st.m]}
